(params: { questionId: string }) => {
  const files = listFiles();
  const relevantFiles = files.filter(file => 
    file.includes('memory') || 
    file.includes('metric') || 
    file.includes('trace') || 
    file.includes('reuse') ||
    file.includes('creation')
  );

  const searchTerms = [
    'memory', 'metric', 'trace', 'reuse', 'creation',
    'function', 'catalogue', 'procedure', 'execution',
    'log', 'track', 'monitor', 'stats', 'count'
  ];

  const results: { file: string; line: number; text: string }[] = [];

  for (const file of relevantFiles) {
    const content = readLines(file, 1, 100).lines;
    for (let i = 0; i < content.length; i++) {
      const lineText = content[i].toLowerCase();
      for (const term of searchTerms) {
        if (lineText.includes(term)) {
          results.push({
            file,
            line: i + 1,
            text: content[i]
          });
        }
      }
    }
  }

  return {
    relevantFiles,
    results
  };
}

