(params: { questionId: string }) => {
  // Lister tous les fichiers et rechercher les occurrences des fonctions mémoire
  const files = listFiles();
  const memoryFunctions = ['memory_list', 'memory_run', 'memory_unusable', 'function_try'];

  const results: { file: string; line: number; text: string; function: string }[] = [];

  for (const file of files) {
    if (
      file.includes('.vscode-test') || 
      file.includes('.scratch') || 
      file.includes('node_modules') || 
      file.includes('Database') || 
      file.includes('Session Storage') || 
      file.includes('Local Storage') ||
      file.endsWith('.log')
    ) {
      continue;
    }

    try {
      const content = readLines(file, 1, 100).lines;
      for (let i = 0; i < content.length; i++) {
        const lineText = content[i];
        for (const func of memoryFunctions) {
          if (lineText.includes(func)) {
            results.push({
              file,
              line: i + 1,
              text: lineText,
              function: func
            });
          }
        }
      }
    } catch (e) {
      // Ignorer les erreurs
    }
  }

  return { results };
}

