(params: { questionId: string }) => {
  // Explorer les fichiers dans le répertoire courant pour identifier les composants liés aux fonctions mémoire
  const files = listFiles();

  // Filtrer les fichiers pertinents (exclure les logs, tests, et fichiers temporaires)
  const relevantFiles = files.filter(file => 
    !file.includes('.vscode-test') && 
    !file.includes('.scratch') && 
    !file.includes('node_modules') && 
    !file.includes('Database') && 
    !file.includes('Session Storage') && 
    !file.includes('Local Storage') && 
    !file.endsWith('.log') &&
    !file.includes('.DS_Store') &&
    (file.endsWith('.ts') || file.endsWith('.js') || file.endsWith('.json') || file.endsWith('.md'))
  );

  // Lire le contenu des fichiers pour identifier les composants, métriques et traces
  const components: { name: string; file: string; startLine: number; endLine: number }[] = [];
  const metrics: { name: string; file: string; startLine: number; endLine: number }[] = [];
  const traces: { name: string; file: string; startLine: number; endLine: number }[] = [];

  for (const file of relevantFiles.slice(0, 20)) { // Limiter à 20 fichiers pour éviter les erreurs
    try {
      const content = readLines(file, 1, 100);

      for (let i = 0; i < content.lines.length; i++) {
        const lineText = content.lines[i].toLowerCase();

        // Rechercher des composants liés aux fonctions mémoire
        if (lineText.includes('memory_list') || lineText.includes('memory_run') || lineText.includes('memory_unusable')) {
          components.push({
            name: lineText.includes('memory_list') ? 'memory_list' : lineText.includes('memory_run') ? 'memory_run' : 'memory_unusable',
            file,
            startLine: i + 1,
            endLine: i + 1
          });
        }

        // Rechercher des métriques
        if (lineText.includes('metric') || lineText.includes('stats') || lineText.includes('count')) {
          metrics.push({
            name: 'metric',
            file,
            startLine: i + 1,
            endLine: i + 1
          });
        }

        // Rechercher des traces
        if (lineText.includes('trace') || lineText.includes('log') || lineText.includes('track')) {
          traces.push({
            name: 'trace',
            file,
            startLine: i + 1,
            endLine: i + 1
          });
        }
      }
    } catch (e) {
      // Ignorer les erreurs de lecture
    }
  }

  return { components, metrics, traces };
}

